const rows = queries.records.data || [];
const s = r => r.stage || r.status || 'Open';
const due = r => r.due_on || r.due || r.event_on || '';
const active = rows.filter(r => !['Complete', 'Completed', 'Closed'].includes(s(r)));
// tiles: same labels and numbers as the original Html (decorative). Real stage counts later = swap this line only.
const tiles = ['Handover', 'Access', 'Equipment', 'Payroll'].map((x, i) => ({ label: x, count: Math.max(0, active.length - i), note: 'open checks' }));
const nextRows = active.slice().sort((a, b) => String(due(a) || '9999').localeCompare(String(due(b) || '9999')));
const p = rows.find(r => r.id === variables.recordId);
const plan = (p?.decisions || []).filter(d => d.type === 'plan').at(-1) || {};
const result = (p?.decisions || []).filter(d => d.type === 'result' && d.version === plan.version).at(-1) || {};
const reviews = (p?.decisions || []).filter(d => d.type === 'review' && d.version === plan.version);
const box = role => { const q = reviews.filter(x => x.role === role).at(-1); return { role, decision: q?.decision || 'Awaiting review', reviewer: q?.reviewer || 'No reviewer recorded', note: q?.note || '' }; };
return {
  tiles,
  next: nextRows.slice(0, 4).map(r => ({ name: r.title || r.name || r.reference || 'Untitled', meta: (r.owner || r.manager || 'Unassigned') + ' · ' + due(r) })),
  file: { context: p?.context || 'Select a record', status: p?.status || 'No record', ownerLine: (p?.owner || '') + ' · Plan ' + (plan.version || '—'),
          employee: plan.employee ?? 'Not recorded', lastDay: plan.lastDay ?? 'Not recorded', handover: plan.handover ?? 'Not recorded', notice: plan.notice ?? 'Not recorded' },
  reviews: [box('People operations'), box('Department manager')],
  outcome: result.type ? Object.entries(result).filter(([k]) => !['type', 'version', 'at'].includes(k)).map(([k, v]) => k.replace(/([A-Z])/g, ' $1') + ': ' + v).join(' · ') : '',
  history: (p?.history || []).slice().reverse().map(h => ({ event: h.event, at: String(h.at || '').slice(0, 16).replace('T', ' '), note: h.note || '' }))
};
